export default function createNode(config, ctx) {
  // Preload texture using context loader
  const textureUrl = config.assets?.imageUrl || '/prism-mock/home/nodes/orb-decor.png';
  const imgTexture = ctx.textureLoader.load(textureUrl);

  // Define procedural grain function (static per pixel, based on UV)
  const grain = Fn(() => {
    const u = uv();
    // Simple hash
    const seed = dot(u, vec2(12.9898, 78.233));
    const noise = sin(seed) * 43758.5453;
    return fract(noise);
  });

  // Define gradient: from surface (dark) to accent (red) bottom-to-top
  const gradientColor = Fn(() => {
    const u = uv();
    const t = smoothstep(0.0, 1.0, u.y);
    const color1 = vec3(0.043, 0.043, 0.039); // near-black surface
    const color2 = vec3(1.0, 0.165, 0.22);   // accent
    return mix(color1, color2, t);
  });

  // Build material: combine gradient, grain, and texture
  const material = new MeshBasicNodeMaterial({
    colorNode: Fn(() => {
      const base = gradientColor();
      const grainVal = grain();
      const grainStrength = float(0.04); // subtle grain
      const grainMix = mix(base, vec3(1.0, 1.0, 1.0), grainVal.mul(grainStrength));
      // Apply texture overlay (multiply, keeping grain)
      const tex = texture(imgTexture, uv());
      return grainMix.mul(tex);
    })(),
    transparent: true,
    side: DoubleSide,
  });

  // Geometry – plane with 1x1 unit, scaled via scale
  const geometry = new PlaneGeometry(1, 1);

  // Mesh
  const mesh = new Mesh(geometry, material);
  mesh.position.set(
    config.scenePosition?.x ?? 0,
    config.scenePosition?.y ?? -0.3,
    config.scenePosition?.z ?? 0
  );
  mesh.rotation.set(
    config.sceneRotation?.x ?? 0,
    config.sceneRotation?.y ?? 0,
    config.sceneRotation?.z ?? 0
  );
  mesh.scale.set(
    config.sceneScale?.x ?? 1,
    config.sceneScale?.y ?? 1,
    config.sceneScale?.z ?? 1
  );

  // UserData: handlers and cleanup
  mesh.userData.handlers = {};

  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    imgTexture.dispose();
  };

  return mesh;
}
